var BIR_TAX_MODE_LABELS = {
	VAT_LUMP_SUM_2PCT: "1. Standard VAT Contractor — 12% VAT + 2% Service/Contractor EWT (on Net of VAT)",
	VAT_SEPARATED_LABOR_MAT: "2. Separated Labor (2% Service EWT) & Materials (1% Item EWT) + 12% VAT",
	NON_VAT_LUMP_OR_SEP: "3. Non-VAT Contractor — 0% VAT; 2% Service/Labor & 1% Material EWT on Gross",
	GOVT_VAT_5PCT_EWT_2PCT: "4. Government / Creditable VAT — 5% Final VAT + 2% EWT (7% on Net of VAT)",
	CUSTOM_MANUAL: "5. Custom / Manual User Overwrite of Tax Values"
};
